import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	Card,
	CardContent,
	CardDescription,
	CardHeader,
	CardTitle,
} from "@/components/ui/card";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { orpc } from "@/utils/orpc";

const statusColors = {
	draft: "bg-neutral-100 text-neutral-600",
	published: "bg-green-100 text-green-700",
	closed: "bg-orange-100 text-orange-700",
	archived: "bg-neutral-100 text-neutral-500",
};

export default function SurveysPage() {
	const [search, setSearch] = useState("");
	const [statusFilter, setStatusFilter] = useState<
		"draft" | "published" | "closed" | "archived" | undefined
	>(undefined);
	const [page, setPage] = useState(1);

	const queryClient = useQueryClient();

	const surveys = useQuery(
		orpc.survey.list.queryOptions({
			input: {
				page,
				limit: 10,
				search: search || undefined,
				status: statusFilter,
			},
		}),
	);

	const deleteMutation = useMutation(
		orpc.survey.delete.mutationOptions({
			onSuccess: () => {
				toast.success("Survey deleted");
				queryClient.invalidateQueries({ queryKey: ["survey", "list"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to delete survey");
			},
		}),
	);

	const changeStatusMutation = useMutation(
		orpc.survey.changeStatus.mutationOptions({
			onSuccess: () => {
				toast.success("Survey status updated");
				queryClient.invalidateQueries({ queryKey: ["survey", "list"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to update status");
			},
		}),
	);

	const handleDelete = (id: string) => {
		if (confirm("Are you sure you want to delete this survey?")) {
			deleteMutation.mutate({ id });
		}
	};

	const handleStatusChange = (
		id: string,
		status: "draft" | "published" | "closed" | "archived",
	) => {
		changeStatusMutation.mutate({ id, status });
	};

	return (
		<div className="mx-auto w-full max-w-6xl p-6">
			<div className="mb-8 flex items-center justify-between">
				<div>
					<h1 className="font-bold text-2xl text-neutral-900">Surveys</h1>
					<p className="text-neutral-500">Create and manage your surveys</p>
				</div>
				<Button asChild>
					<Link href="/surveys/new">
						<Plus className="mr-2 h-4 w-4" />
						Create Survey
					</Link>
				</Button>
			</div>

			{/* Filters */}
			<div className="mb-6 flex flex-wrap items-center gap-4">
				<div className="relative min-w-[200px] flex-1">
					<Search className="absolute top-1/2 left-3 h-4 w-4 -translate-y-1/2 text-neutral-400" />
					<Input
						placeholder="Search surveys..."
						value={search}
						onChange={(e) => {
							setSearch(e.target.value);
							setPage(1);
						}}
						className="pl-10"
					/>
				</div>
				<div className="flex gap-2">
					{(["draft", "published", "closed", "archived"] as const).map(
						(status) => (
							<Button
								key={status}
								variant={statusFilter === status ? "default" : "outline"}
								size="sm"
								onClick={() => {
									setStatusFilter(statusFilter === status ? undefined : status);
									setPage(1);
								}}
							>
								{status.charAt(0).toUpperCase() + status.slice(1)}
							</Button>
						),
					)}
				</div>
			</div>

			{/* Survey List */}
			{surveys.isLoading ? (
				<div className="flex justify-center py-12">
					<Loader2 className="h-8 w-8 animate-spin text-neutral-400" />
				</div>
			) : surveys.data?.data.length === 0 ? (
				<Card className="border-dashed">
					<CardContent className="flex flex-col items-center justify-center py-16">
						<ClipboardList className="mb-4 h-12 w-12 text-neutral-300" />
						<CardTitle className="mb-2">No surveys yet</CardTitle>
						<CardDescription className="mb-4 text-center">
							Create your first survey to start collecting responses
						</CardDescription>
						<Button asChild>
							<Link href="/surveys/new">
								<Plus className="mr-2 h-4 w-4" />
								Create Survey
							</Link>
						</Button>
					</CardContent>
				</Card>
			) : (
				<div className="space-y-4">
					{surveys.data?.data.map((survey) => (
						<Card
							key={survey.id}
							className="transition-colors hover:border-neutral-300"
						>
							<CardHeader className="pb-3">
								<div className="flex items-start justify-between">
									<div className="flex-1">
										<div className="flex items-center gap-3">
											<Link
												href={`/surveys/${survey.id}`}
												className="font-semibold text-lg hover:text-violet-600"
											>
												{survey.title}
											</Link>
											<Badge
												variant="secondary"
												className={statusColors[survey.status]}
											>
												{survey.status}
											</Badge>
										</div>
										{survey.description && (
											<CardDescription className="mt-1">
												{survey.description}
											</CardDescription>
										)}
									</div>
									<DropdownMenu>
										<DropdownMenuTrigger
											render={<Button variant="ghost" size="icon" />}
										>
											<MoreHorizontal className="h-4 w-4" />
										</DropdownMenuTrigger>
										<DropdownMenuContent align="end">
											<DropdownMenuItem>
												<Link
													href={`/surveys/${survey.id}`}
													className="flex items-center"
												>
													<Edit className="mr-2 h-4 w-4" />
													Edit
												</Link>
											</DropdownMenuItem>
											<DropdownMenuItem>
												<Link
													href={
														`/surveys/${survey.id}/analytics` as unknown as string
													}
													className="flex items-center"
												>
													<BarChart3 className="mr-2 h-4 w-4" />
													Analytics
												</Link>
											</DropdownMenuItem>
											{survey.status === "draft" && (
												<DropdownMenuItem
													onClick={() =>
														handleStatusChange(survey.id, "published")
													}
												>
													<ClipboardList className="mr-2 h-4 w-4" />
													Publish
												</DropdownMenuItem>
											)}
											{survey.status === "published" && (
												<DropdownMenuItem
													onClick={() =>
														handleStatusChange(survey.id, "closed")
													}
												>
													<Archive className="mr-2 h-4 w-4" />
													Close
												</DropdownMenuItem>
											)}
											<DropdownMenuSeparator />
											<DropdownMenuItem
												className="text-red-600"
												onClick={() => handleDelete(survey.id)}
											>
												<Trash2 className="mr-2 h-4 w-4" />
												Delete
											</DropdownMenuItem>
										</DropdownMenuContent>
									</DropdownMenu>
								</div>
							</CardHeader>
							<CardContent>
								<div className="flex items-center gap-6 text-neutral-500 text-sm">
									<div className="flex items-center gap-1">
										<Calendar className="h-4 w-4" />
										{new Date(survey.createdAt).toLocaleDateString()}
									</div>
									<div className="flex items-center gap-1">
										<ClipboardList className="h-4 w-4" />/{survey.slug}
									</div>
								</div>
							</CardContent>
						</Card>
					))}
				</div>
			)}

			{/* Pagination */}
			{surveys.data && surveys.data.pagination.totalPages > 1 && (
				<div className="mt-6 flex justify-center gap-2">
					<Button
						variant="outline"
						size="sm"
						disabled={page === 1}
						onClick={() => setPage(page - 1)}
					>
						Previous
					</Button>
					<span className="flex items-center px-4 text-sm">
						Page {page} of {surveys.data.pagination.totalPages}
					</span>
					<Button
						variant="outline"
						size="sm"
						disabled={page >= surveys.data.pagination.totalPages}
						onClick={() => setPage(page + 1)}
					>
						Next
					</Button>
				</div>
			)}
		</div>
	);
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { motion } from "framer-motion";
import {
	ArrowLeft,
	BarChart3,
	Eye,
	Hammer,
	Loader2,
	MoreHorizontal,
	Send,
	Settings,
	Share2,
} from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { orpc } from "@/utils/orpc";

import { useSurveyBuilder } from "./index";
import { SurveySettingsDialog } from "./survey-settings-dialog";

const statusColors: Record<string, string> = {
	draft: "bg-neutral-100 text-neutral-600",
	published: "bg-green-100 text-green-700",
	closed: "bg-orange-100 text-orange-700",
	archived: "bg-neutral-100 text-neutral-500",
};

interface BuilderHeaderProps {
	leftActions?: React.ReactNode;
	rightActions?: React.ReactNode;
}

export function BuilderHeader({
	leftActions,
	rightActions,
}: BuilderHeaderProps) {
	const { survey, activeTab, setActiveTab, settingsOpen, setSettingsOpen } =
		useSurveyBuilder();
	const queryClient = useQueryClient();

	const publishMutation = useMutation(
		orpc.survey.changeStatus.mutationOptions({
			onSuccess: () => {
				toast.success("Survey published!");
				queryClient.invalidateQueries({ queryKey: ["survey"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to publish survey");
			},
		}),
	);

	const handlePublish = () => {
		if (survey.status === "draft") {
			publishMutation.mutate({ id: survey.id, status: "published" });
		}
	};

	return (
		<header className="z-20 flex shrink-0 items-center justify-between border-neutral-100 border-b bg-white px-6 py-3">
			<div className="flex items-center gap-4">
				{leftActions}
				<Button variant="ghost" size="sm" asChild>
					<Link href="/surveys">
						<ArrowLeft className="mr-2 h-4 w-4" />
						Back
					</Link>
				</Button>
				<div className="flex items-center gap-2 font-sans font-semibold text-neutral-900 text-sm">
					<span className="text-neutral-400">Surveys /</span>
					<span>{survey.title}</span>
					<Badge variant="secondary" className={statusColors[survey.status]}>
						{survey.status}
					</Badge>
				</div>
			</div>

			{/* Tab Navigation with animated indicator */}
			<div className="flex gap-1 rounded-lg bg-neutral-100 p-1">
				<button
					type="button"
					onClick={() => setActiveTab("build")}
					className={`relative flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "build"
							? "text-neutral-900"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					{activeTab === "build" && (
						<motion.div
							layoutId="activeTab"
							className="absolute inset-0 rounded-md bg-white shadow-sm"
							transition={{ type: "spring", stiffness: 500, damping: 30 }}
						/>
					)}
					<span className="relative z-10 flex items-center gap-2">
						<Hammer className="h-3.5 w-3.5" />
						Build
					</span>
				</button>
				<button
					type="button"
					onClick={() => setActiveTab("preview")}
					className={`relative flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "preview"
							? "text-neutral-900"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					{activeTab === "preview" && (
						<motion.div
							layoutId="activeTab"
							className="absolute inset-0 rounded-md bg-white shadow-sm"
							transition={{ type: "spring", stiffness: 500, damping: 30 }}
						/>
					)}
					<span className="relative z-10 flex items-center gap-2">
						<Eye className="h-3.5 w-3.5" />
						Preview
					</span>
				</button>
				{survey.status === "published" && (
					<button
						type="button"
						onClick={() => setActiveTab("share")}
						className={`relative flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
							activeTab === "share"
								? "text-neutral-900"
								: "text-neutral-500 hover:text-neutral-900"
						}`}
					>
						{activeTab === "share" && (
							<motion.div
								layoutId="activeTab"
								className="absolute inset-0 rounded-md bg-white shadow-sm"
								transition={{ type: "spring", stiffness: 500, damping: 30 }}
							/>
						)}
						<span className="relative z-10 flex items-center gap-2">
							<Share2 className="h-3.5 w-3.5" />
							Share
						</span>
					</button>
				)}
			</div>

			<div className="flex items-center gap-3">
				{rightActions}
				<DropdownMenu>
					<DropdownMenuTrigger render={<Button variant="ghost" size="icon" />}>
						<MoreHorizontal className="h-4 w-4" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="end">
						<DropdownMenuItem>
							<Link
								href={
									`/surveys/${survey.id}/analytics` as unknown as string
								}
								className="flex items-center"
							>
								<BarChart3 className="mr-2 h-4 w-4" />
								Analytics
							</Link>
						</DropdownMenuItem>
						<DropdownMenuItem onClick={() => setSettingsOpen(true)}>
							<Settings className="mr-2 h-4 w-4" />
							Survey Settings
						</DropdownMenuItem>
						<DropdownMenuSeparator />
						<DropdownMenuItem className="text-red-600">
							Delete Survey
						</DropdownMenuItem>
					</DropdownMenuContent>
				</DropdownMenu>

				{survey.status === "draft" ? (
					<Button onClick={handlePublish} disabled={publishMutation.isPending}>
						{publishMutation.isPending ? (
							<Loader2 className="mr-2 h-4 w-4 animate-spin" />
						) : (
							<Send className="mr-2 h-4 w-4" />
						)}
						Publish
					</Button>
				) : (
					<Button variant="outline" asChild>
						<a
							href={`/s/${survey.slug}`}
							target="_blank"
							rel="noopener noreferrer"
						>
							<Eye className="mr-2 h-4 w-4" />
							View Survey
						</a>
					</Button>
				)}
			</div>

			<SurveySettingsDialog
				open={settingsOpen}
				onOpenChange={setSettingsOpen}
			/>
		</header>
	);
}

"use client";

