   123→												onChangeText={field.handleChange}
   124→												placeholder="email@example.com"
   125→												keyboardType="email-address"
   126→												autoCapitalize="none"
   127→												autoComplete="email"
   128→												textContentType="emailAddress"
   129→												returnKeyType="next"
   130→												blurOnSubmit={false}
   131→												onSubmitEditing={() => {
   132→													passwordInputRef.current?.focus();
   133→												}}
   134→											/>
   135→										</TextField>
   136→									)}
   137→								</form.Field>
   138→
   139→								<form.Field name="password">
   140→									{(field) => (
   141→										<TextField>
   142→											<Label>Password</Label>
   143→											<Input
   144→												ref={passwordInputRef}
   145→												value={field.state.value}
   146→												onBlur={field.handleBlur}
   147→												onChangeText={field.handleChange}
   148→												placeholder="••••••••"
   149→												secureTextEntry
   150→												autoComplete="password"
   151→												textContentType="password"
   152→												returnKeyType="go"
   153→												onSubmitEditing={form.handleSubmit}
   154→											/>
   155→										</TextField>
   156→									)}
   157→								</form.Field>
   158→
   159→								<Button
   160→									onPress={form.handleSubmit}
