     1→import type React from "react";
     2→import { createContext, useCallback, useContext, useMemo } from "react";
     3→import { Uniwind, useUniwind } from "uniwind";
     4→
     5→type ThemeName = "light" | "dark";
     6→
     7→type AppThemeContextType = {
     8→	currentTheme: string;
     9→	isLight: boolean;
    10→	isDark: boolean;
    11→	setTheme: (theme: ThemeName) => void;
    12→	toggleTheme: () => void;
    13→};
    14→
    15→const AppThemeContext = createContext<AppThemeContextType | undefined>(
    16→	undefined,
    17→);
    18→
    19→export const AppThemeProvider = ({
    20→	children,
    21→}: {
    22→	children: React.ReactNode;
    23→}) => {
    24→	const { theme } = useUniwind();
    25→
    26→	const isLight = useMemo(() => {
    27→		return theme === "light";
    28→	}, [theme]);
    29→
    30→	const isDark = useMemo(() => {
    31→		return theme === "dark";
    32→	}, [theme]);
    33→
    34→	const setTheme = useCallback((newTheme: ThemeName) => {
    35→		Uniwind.setTheme(newTheme);
    36→	}, []);
    37→
    38→	const toggleTheme = useCallback(() => {
    39→		Uniwind.setTheme(theme === "light" ? "dark" : "light");
    40→	}, [theme]);
    41→
    42→	const value = useMemo(
    43→		() => ({
    44→			currentTheme: theme,
    45→			isLight,
    46→			isDark,
    47→			setTheme,
    48→			toggleTheme,
    49→		}),
    50→		[theme, isLight, isDark, setTheme, toggleTheme],
    51→	);
    52→
    53→	return (
    54→		<AppThemeContext.Provider value={value}>
    55→			{children}
    56→		</AppThemeContext.Provider>
    57→	);
    58→};
    59→
    60→export function useAppTheme() {
    61→	const context = useContext(AppThemeContext);
    62→	if (!context) {
    63→		throw new Error("useAppTheme must be used within AppThemeProvider");
    64→	}
    65→	return context;
    66→}
