   475→export function QuestionRenderer({ question }: QuestionRendererProps) {
   476→	const { answers, setAnswer, currentError } = useSurveyRunner();
   477→	const value = answers.get(question.id);
   478→	const error = currentError;
   479→
   480→	const handleChange = (newValue: unknown) => {
   481→		setAnswer(question.id, newValue);
   482→	};
   483→
   484→	switch (question.type) {
   485→		case "text":
   486→			return (
   487→				<TextQuestion
   488→					question={question}
   489→					value={value as string | undefined}
   490→					onChange={(v) => handleChange(v)}
   491→					error={error}
   492→				/>
   493→			);
   494→		case "textarea":
   495→			return (
   496→				<TextareaQuestion
   497→					question={question}
   498→					value={value as string | undefined}
   499→					onChange={(v) => handleChange(v)}
   500→					error={error}
   501→				/>
   502→			);
   503→		case "multiple_choice":
   504→			return (
   505→				<ChoiceQuestion
   506→					question={question}
   507→					value={value as string | undefined}
   508→					onChange={(v) => handleChange(v)}
   509→					error={error}
   510→				/>
   511→			);
   512→		case "checkbox":
   513→			return (
   514→				<CheckboxQuestion
   515→					question={question}
   516→					value={value as string[] | undefined}
   517→					onChange={(v) => handleChange(v)}
   518→					error={error}
   519→				/>
   520→			);
   521→		case "dropdown":
   522→			return (
   523→				<DropdownQuestion
   524→					question={question}
   525→					value={value as string | undefined}
   526→					onChange={(v) => handleChange(v)}
   527→					error={error}
   528→				/>
   529→			);
   530→		case "rating":
   531→			return (
   532→				<RatingQuestion
   533→					question={question}
   534→					value={value as number | undefined}
   535→					onChange={(v) => handleChange(v)}
   536→					error={error}
   537→				/>
   538→			);
   539→		case "nps":
   540→			return (
   541→				<NpsQuestion
   542→					question={question}
   543→					value={value as number | undefined}
   544→					onChange={(v) => handleChange(v)}
   545→					error={error}
   546→				/>
   547→			);
   548→		case "linear_scale":
   549→			return (
   550→				<LinearScaleQuestion
   551→					question={question}
   552→					value={value as number | undefined}
   553→					onChange={(v) => handleChange(v)}
   554→					error={error}
   555→				/>
   556→			);
   557→		case "date":
   558→			return (
   559→				<DateQuestion
   560→					question={question}
   561→					value={value as string | undefined}
   562→					onChange={(v) => handleChange(v)}
