   564→				/>
   565→			);
   566→		case "email":
   567→			return (
   568→				<EmailQuestion
   569→					question={question}
   570→					value={value as string | undefined}
   571→					onChange={(v) => handleChange(v)}
   572→					error={error}
   573→				/>
   574→			);
   575→		case "phone":
   576→			return (
   577→				<PhoneQuestion
   578→					question={question}
