   204→			const optimisticQuestions = [
   205→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   206→				{ ...optimisticQuestion, order: insertIndex },
   207→				...questions
   208→					.slice(insertIndex)
   209→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   210→			];
   211→
   212→			setQuestions(optimisticQuestions);
   213→			setSelectedQuestionId(tempId);
   214→
   215→			// Create question and reorder
   216→			client.question
   217→				.create({
   218→					surveyId: survey.id,
   219→					type: questionType,
   220→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   221→					order: insertIndex,
   222→				})
