   238→					// Reorder all questions on backend to ensure consistency
   239→					const finalQuestions = [
   240→						...questions
   241→							.slice(0, insertIndex)
   242→							.map((q, i) => ({ ...q, order: i })),
   243→						{ ...newQuestion, order: insertIndex },
   244→						...questions
   245→							.slice(insertIndex)
   246→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   247→					];
   248→
   249→					reorderMutation.mutate({
   250→						questions: finalQuestions.map((q) => ({
   251→							id: q.id,
   252→							order: q.order,
   253→						})),
   254→					});
