   300→		survey,
   301→		questions,
   302→		selectedQuestionId,
   303→		setSelectedQuestionId,
   304→		activeTab,
   305→		setActiveTab,
   306→		onQuestionsChange: setQuestions,
   307→		paletteOpen,
   308→		setPaletteOpen,
   309→		propertiesOpen,
   310→		setPropertiesOpen,
   311→		settingsOpen,
   312→		setSettingsOpen,
   313→	};
   314→
   315→	const safeQuestions = questions || [];
   316→
   317→	// Render drag overlay
   318→	const renderDragOverlay = () => {
   319→		if (!activeDragItem) return null;
   320→
   321→		if (activeDragItem.type === "palette") {
   322→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
