   355→	return (
   356→		<SurveyBuilderContext.Provider value={contextValue}>
   357→			<DndContext
   358→				sensors={sensors}
   359→				collisionDetection={collisionDetection}
   360→				onDragStart={handleDragStart}
   361→				onDragOver={handleDragOver}
   362→				onDragEnd={handleDragEnd}
   363→			>
   364→				<div className={cn("flex h-full flex-col", className)}>
   365→					<BuilderHeader
   366→						leftActions={
   367→							!isDesktop &&
   368→							activeTab === "build" && (
   369→								<div className="flex items-center gap-1">
   370→									<Button
   371→										variant="ghost"
   372→										size="icon"
   373→										onClick={() => setPaletteOpen(!paletteOpen)}
   374→									>
   375→										<PanelLeftClose className="h-4 w-4" />
   376→									</Button>
   377→								</div>
   378→							)
   379→						}
   380→						rightActions={
   381→							!isDesktop &&
   382→							activeTab === "build" && (
   383→								<div className="flex items-center gap-1">
   384→									<Button
   385→										variant="ghost"
   386→										size="icon"
   387→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   388→									>
   389→										<PanelRightClose className="h-4 w-4" />
   390→									</Button>
   391→								</div>
   392→							)
   393→						}
   394→					/>
   395→					<div className="flex flex-1 overflow-hidden">
   396→						{/* Left Palette - Responsive */}
   397→						{activeTab === "build" && (
   398→							<>
   399→								{/* Desktop: Fixed sidebar */}
   400→								{isDesktop && <QuestionPalette />}
   401→
   402→								{/* Tablet/Mobile: Sheet overlay */}
   403→								{!isDesktop && (
   404→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   405→										<SheetContent side="left" className="w-72 p-0">
   406→											<QuestionPalette />
   407→										</SheetContent>
   408→									</Sheet>
   409→								)}
   410→							</>
   411→						)}
   412→
   413→						{/* Canvas */}
   414→						<BuilderCanvas
   415→							questions={questions}
   416→							onQuestionsChange={setQuestions}
   417→							activeDragItem={activeDragItem}
   418→							overId={overId}
   419→						/>
   420→
   421→						{/* Right Properties Panel - Responsive */}
   422→						{activeTab === "build" && (
