   224→								<CardDescription>
   225→									{questionTypeLabels[qa.questionType] || qa.questionType} •{" "}
   226→									{qa.totalAnswers} answers
   227→								</CardDescription>
   228→							</CardHeader>
   229→							<CardContent>{renderChart(qa)}</CardContent>
