    12→	type: "rating" | "nps" | "linear_scale";
    13→}
    14→
    15→export function RatingEditor({ config, onChange, type }: RatingEditorProps) {
    16→	if (type === "nps") {
    17→		return <NPSEditor config={config} onChange={onChange} />;
    18→	}
    19→
    20→	if (type === "linear_scale") {
