    26→
    27→function RatingScaleEditor({
    28→	config,
    29→	onChange,
    30→}: {
    31→	config: QuestionConfig;
    32→	onChange: (config: QuestionConfig) => void;
    33→}) {
    34→	const handleMaxChange = (value: string) => {
    35→		const max = value ? Math.min(10, Math.max(1, Number(value))) : 5;
    36→		onChange({ ...config, max });
    37→	};
    38→
    39→	return (
    40→		<div className="space-y-4">
    41→			<div className="space-y-2">
