    45→				<div className="flex items-center gap-2">
    46→					<Input
    47→						type="number"
    48→						value={config.max || 5}
    49→						onChange={(e) => handleMaxChange(e.target.value)}
    50→						min={1}
    51→						max={10}
    52→						className="w-20"
    53→					/>
    54→					<span className="text-neutral-500 text-sm">stars</span>
    55→				</div>
    56→			</div>
    57→
    58→			<div className="flex items-center justify-between rounded-lg bg-neutral-50 p-3">
    59→				<span className="text-neutral-600 text-sm">Preview:</span>
    60→				<div className="flex gap-1">
    61→					{Array.from({ length: config.max || 5 }).map((_, i) => (
    62→						<Star
    63→							// biome-ignore lint/suspicious/noArrayIndexKey: Static preview
    64→							key={i}
    65→							className="h-5 w-5 fill-violet-500 text-violet-500"
