   120→
   121→function LinearScaleEditor({
   122→	config,
   123→	onChange,
   124→}: {
   125→	config: QuestionConfig;
   126→	onChange: (config: QuestionConfig) => void;
   127→}) {
   128→	const min = config.min ?? 1;
   129→	const max = config.max ?? 5;
   130→
   131→	const handleMinChange = (value: string) => {
   132→		const newMin = value ? Number(value) : 1;
   133→		onChange({ ...config, min: newMin });
   134→	};
   135→
   136→	const handleMaxChange = (value: string) => {
   137→		const newMax = value ? Number(value) : 5;
   138→		onChange({ ...config, max: newMax });
   139→	};
   140→
   141→	const scaleValues = [];
   142→	for (let i = min; i <= max; i++) {
   143→		scaleValues.push(i);
   144→	}
   145→
   146→	return (
   147→		<div className="space-y-4">
   148→			<div className="grid grid-cols-2 gap-3">
   149→				<div className="space-y-2">
   150→					<Label className="text-xs uppercase tracking-wide">Min Value</Label>
   151→					<Input
   152→						type="number"
   153→						value={min}
   154→						onChange={(e) => handleMinChange(e.target.value)}
   155→						min={0}
   156→						max={max - 1}
   157→					/>
   158→				</div>
   159→				<div className="space-y-2">
   160→					<Label className="text-xs uppercase tracking-wide">Max Value</Label>
   161→					<Input
   162→						type="number"
   163→						value={max}
   164→						onChange={(e) => handleMaxChange(e.target.value)}
   165→						min={min + 1}
   166→						max={10}
   167→					/>
   168→				</div>
   169→			</div>
   170→
   171→			<div className="space-y-2">
   172→				<Label className="text-xs uppercase tracking-wide">Step</Label>
   173→				<Input
   174→					type="number"
   175→					value={config.step || 1}
   176→					onChange={(e) =>
   177→						onChange({
   178→							...config,
   179→							step: e.target.value ? Number(e.target.value) : 1,
   180→						})
   181→					}
   182→					min={1}
   183→					max={max - min}
   184→				/>
   185→			</div>
   186→
   187→			<div className="flex items-center justify-between rounded-lg bg-neutral-50 p-3">
   188→				<span className="text-neutral-600 text-sm">Preview:</span>
   189→				<div className="flex gap-1">
   190→					{scaleValues.map((num) => (
   191→						<div
   192→							key={num}
   193→							className="flex h-7 w-7 items-center justify-center rounded border border-neutral-200 text-xs"
   194→						>
   195→							{num}
   196→						</div>
   197→					))}
   198→				</div>
   199→			</div>
   200→		</div>
   201→	);
   202→}
