     3→import type { QuestionConfig } from "@orksys-survey/db";
     4→import { Plus, Trash2 } from "lucide-react";
     5→
     6→import { Button } from "@/components/ui/button";
     7→import { Input } from "@/components/ui/input";
     8→import { Label } from "@/components/ui/label";
     9→import { Switch } from "@/components/ui/switch";
    10→
    11→interface ChoiceEditorProps {
    12→	config: QuestionConfig;
    13→	onChange: (config: QuestionConfig) => void;
    14→	allowMultiple?: boolean;
    15→}
    16→
    17→export function ChoiceEditor({
    18→	config,
    19→	onChange,
    20→	allowMultiple = false,
    21→}: ChoiceEditorProps) {
    22→	const options = config.options || [
    23→		{ label: "Option 1", value: "option_1" },
    24→		{ label: "Option 2", value: "option_2" },
    25→	];
    26→
    27→	const handleAddOption = () => {
    28→		const newOption = {
    29→			label: `Option ${options.length + 1}`,
    30→			value: `option_${options.length + 1}`,
    31→		};
    32→		onChange({ ...config, options: [...options, newOption] });
    33→	};
    34→
    35→	const handleUpdateOption = (
    36→		index: number,
    37→		field: "label" | "value",
    38→		newValue: string,
    39→	) => {
    40→		const updatedOptions = options.map((opt, i) =>
    41→			i === index ? { ...opt, [field]: newValue } : opt,
    42→		);
    43→		onChange({ ...config, options: updatedOptions });
    44→	};
    45→
    46→	const handleDeleteOption = (index: number) => {
    47→		const updatedOptions = options.filter((_, i) => i !== index);
    48→		onChange({ ...config, options: updatedOptions });
    49→	};
    50→
    51→	const handleToggleAllowOther = (checked: boolean) => {
    52→		onChange({ ...config, allowOther: checked });
    53→	};
    54→
    55→	const handleToggleAllowMultiple = (checked: boolean) => {
    56→		onChange({ ...config, allowMultiple: checked });
    57→	};
    58→
    59→	return (
    60→		<div className="space-y-4">
    61→			<div className="space-y-2">
    62→				<Label className="text-xs uppercase tracking-wide">Options</Label>
    63→				<div className="space-y-2">
    64→					{options.map((option, index) => (
    65→						<OptionItem
    66→							key={option.value}
    67→							label={option.label}
    68→							onChangeLabel={(label) =>
    69→								handleUpdateOption(index, "label", label)
    70→							}
    71→							onDelete={() => handleDeleteOption(index)}
    72→							canDelete={options.length > 1}
    73→						/>
    74→					))}
    75→				</div>
    76→				<Button
    77→					variant="outline"
    78→					size="sm"
    79→					className="w-full"
    80→					onClick={handleAddOption}
    81→				>
    82→					<Plus className="mr-2 h-4 w-4" />
    83→					Add Option
    84→				</Button>
    85→			</div>
    86→
    87→			<div className="space-y-3 border-neutral-100 border-t pt-4">
    88→				<div className="flex items-center justify-between">
    89→					<div className="flex flex-col">
    90→						<span className="font-medium text-neutral-900 text-sm">
    91→							Allow "Other"
    92→						</span>
    93→						<span className="text-neutral-400 text-xs">
    94→							Let respondents add their own answer
    95→						</span>
    96→					</div>
    97→					<Switch
    98→						checked={config.allowOther || false}
    99→						onCheckedChange={handleToggleAllowOther}
   100→					/>
   101→				</div>
   102→
   103→				{allowMultiple && (
   104→					<div className="flex items-center justify-between">
   105→						<div className="flex flex-col">
   106→							<span className="font-medium text-neutral-900 text-sm">
   107→								Allow Multiple
   108→							</span>
   109→							<span className="text-neutral-400 text-xs">
   110→								Let respondents select multiple options
   111→							</span>
   112→						</div>
   113→						<Switch
   114→							checked={config.allowMultiple || false}
   115→							onCheckedChange={handleToggleAllowMultiple}
   116→						/>
   117→					</div>
   118→				)}
   119→			</div>
   120→		</div>
   121→	);
   122→}
   123→
   124→interface OptionItemProps {
   125→	label: string;
   126→	onChangeLabel: (label: string) => void;
   127→	onDelete: () => void;
   128→	canDelete: boolean;
   129→}
   130→
   131→function OptionItem({
   132→	label,
   133→	onChangeLabel,
   134→	onDelete,
   135→	canDelete,
   136→}: OptionItemProps) {
   137→	return (
   138→		<div className="flex items-center gap-2">
   139→			<Input
   140→				value={label}
   141→				onChange={(e) => onChangeLabel(e.target.value)}
   142→				className="flex-1"
   143→				placeholder="Option text"
   144→			/>
   145→			<Button
   146→				variant="ghost"
   147→				size="icon"
   148→				className="shrink-0"
   149→				onClick={onDelete}
   150→				disabled={!canDelete}
   151→			>
   152→				<Trash2 className="h-4 w-4 text-neutral-400" />
   153→			</Button>
   154→		</div>
   155→	);
   156→}
