    28→					<Button
    29→						variant="ghost"
    30→						onClick={goBack}
    31→						disabled={!canGoBack}
    32→						className="text-neutral-600"
    33→					>
    34→						<ArrowLeft className="mr-2 h-4 w-4" />
    35→						Back
    36→					</Button>
    37→
    38→					{canGoNext ? (
    39→						<Button
