    67→
    68→function ListModeNavigation() {
    69→	const { isSubmitting, submit, validateAllQuestions, visibleQuestions } =
    70→		useSurveyRunner();
    71→
    72→	const [validationErrors, setValidationErrors] = useState<Map<string, string>>(
    73→		new Map(),
    74→	);
    75→
    76→	const handleSubmit = async () => {
    77→		const errors = validateAllQuestions();
    78→		if (errors.size > 0) {
    79→			setValidationErrors(errors);
    80→			return;
    81→		}
    82→		setValidationErrors(new Map());
    83→		await submit();
    84→	};
    85→
    86→	const hasErrors = validationErrors.size > 0;
    87→	const errorMessage = hasErrors
    88→		? `Please answer all required questions (${validationErrors.size} missing)`
    89→		: null;
    90→
    91→	return (
    92→		<div className="border-neutral-200 border-t bg-white px-6 py-4">
    93→			<div className="mx-auto max-w-2xl space-y-3">
    94→				{errorMessage && (
    95→					<div className="rounded-lg bg-red-50 px-4 py-2 text-center text-red-600 text-sm">
    96→						{errorMessage}
    97→					</div>
    98→				)}
    99→				<div className="flex items-center justify-center">
   100→					<Button
   101→						onClick={handleSubmit}
   102→						disabled={isSubmitting}
   103→						className="bg-neutral-900 hover:bg-neutral-800"
   104→					>
   105→						{isSubmitting ? (
   106→							<>
   107→								<Loader2 className="mr-2 h-4 w-4 animate-spin" />
   108→								Submitting...
   109→							</>
   110→						) : (
   111→							`Submit (${visibleQuestions.length} questions)`
   112→						)}
   113→					</Button>
   114→				</div>
   115→			</div>
   116→		</div>
   117→	);
   118→}
