   120→export function RunnerNavigation() {
   121→	const { displayMode } = useSurveyRunner();
   122→
   123→	if (displayMode === "list") {
   124→		return <ListModeNavigation />;
   125→	}
   126→
   127→	return <OneAtATimeNavigation />;
