    23→
    24→export type AnswerValue = unknown;
    25→
    26→interface SurveyRunnerContextValue {
    27→	// Survey data
    28→	survey: Survey;
    29→	questions: Question[];
    30→	settings: SurveySettings | null;
    31→	logicRules: LogicRule[];
    32→	displayMode: "one_at_a_time" | "list";
    33→
    34→	// Response state
    35→	answers: Map<string, AnswerValue>;
    36→	currentQuestionIndex: number;
    37→	visibleQuestionIds: Set<string>;
    38→	visibleQuestions: Question[];
    39→
    40→	// Navigation
    41→	canGoBack: boolean;
    42→	canGoNext: boolean;
    43→	isComplete: boolean;
    44→	isSubmitting: boolean;
    45→
    46→	// Actions
