    48→	goNext: () => void;
    49→	goBack: () => void;
    50→	submit: () => Promise<void>;
    51→	validateAllQuestions: () => Map<string, string>;
    52→
    53→	// Metadata
    54→	fingerprint: string | null;
    55→
    56→	// Error state
    57→	currentError: string | null;
    58→	clearError: () => void;
    59→}
    60→
    61→const SurveyRunnerContext = createContext<SurveyRunnerContextValue | null>(
    62→	null,
    63→);
    64→
    65→export function useSurveyRunner() {
    66→	const context = useContext(SurveyRunnerContext);
    67→	if (!context) {
    68→		throw new Error(
    69→			"useSurveyRunner must be used within a SurveyRunner component",
    70→		);
    71→	}
    72→	return context;
    73→}
    74→
    75→interface SurveyRunnerProviderProps {
    76→	survey: Survey;
    77→	questions: Question[];
    78→	logicRules?: LogicRule[];
    79→	children: React.ReactNode;
    80→	onComplete?: () => void;
    81→}
    82→
    83→export function SurveyRunnerProvider({
    84→	survey,
    85→	questions: allQuestions,
    86→	logicRules = [],
    87→	children,
    88→	onComplete,
    89→}: SurveyRunnerProviderProps) {
    90→	const router = useRouter();
    91→	const fingerprint = useFingerprint();
    92→	const [answers, setAnswers] = useState<Map<string, AnswerValue>>(new Map());
    93→	const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    94→	const [currentError, setCurrentError] = useState<string | null>(null);
    95→	const [isComplete, setIsComplete] = useState(false);
    96→
    97→	// Sort questions by order
    98→	const sortedQuestions = useMemo(
    99→		() => [...allQuestions].sort((a, b) => a.order - b.order),
   100→		[allQuestions],
   101→	);
   102→
   103→	// Evaluate logic to determine visibility
   104→	const { visibleQuestionIds } = useLogicEvaluator({
   105→		rules: logicRules,
   106→		answers,
   107→		questions: sortedQuestions,
   108→		currentQuestionId: sortedQuestions[currentQuestionIndex]?.id,
   109→	});
   110→
   111→	// Get visible questions
   112→	const visibleQuestions = useMemo(
   113→		() => sortedQuestions.filter((q) => visibleQuestionIds.has(q.id)),
   114→		[sortedQuestions, visibleQuestionIds],
   115→	);
   116→
   117→	// Get current visible question
   118→	const currentVisibleIndex = useMemo(() => {
   119→		const currentId = sortedQuestions[currentQuestionIndex]?.id;
   120→		if (!currentId) return 0;
   121→		return visibleQuestions.findIndex((q) => q.id === currentId);
   122→	}, [sortedQuestions, currentQuestionIndex, visibleQuestions]);
   123→
   124→	const currentQuestion = visibleQuestions[currentVisibleIndex];
   125→
   126→	// Navigation state
   127→	const canGoBack = currentVisibleIndex > 0;
   128→	const canGoNext = currentVisibleIndex < visibleQuestions.length - 1;
   129→
   130→	// Submit mutation
   131→	const submitMutation = useMutation({
   132→		mutationFn: async () => {
   133→			const answersArray = Array.from(answers.entries()).map(
   134→				([questionId, value]) => ({
   135→					questionId,
   136→					value,
   137→				}),
   138→			);
   139→
   140→			return client.response.submit({
   141→				surveyId: survey.id,
   142→				fingerprint: fingerprint ?? undefined,
   143→				answers: answersArray,
   144→				isComplete: true,
   145→				metadata: {
   146→					userAgent: navigator.userAgent,
   147→					language: navigator.language,
   148→					timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
   149→				},
   150→			});
   151→		},
   152→		onSuccess: () => {
   153→			setIsComplete(true);
   154→			if (onComplete) {
   155→				onComplete();
   156→			} else {
   157→				// Navigate to complete page
   158→				const completeUrl = `/s/${survey.slug}/complete`;
   159→				const settings = survey.settings as SurveySettings | null;
   160→				if (settings?.thankYouMessage || settings?.redirectUrl) {
   161→					const params = new URLSearchParams();
   162→					if (settings.thankYouMessage) {
   163→						params.set("message", settings.thankYouMessage);
   164→					}
   165→					if (settings.redirectUrl) {
   166→						params.set("redirectUrl", settings.redirectUrl);
   167→					}
   168→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   169→					router.push(`${completeUrl}?${params.toString()}` as any);
   170→				} else {
   171→					// eslint-disable-next-line @typescript-eslint/no-explicit-any
   172→					router.push(completeUrl as any);
   173→				}
   174→			}
   175→		},
   176→		onError: (error) => {
   177→			toast.error(error.message || "Failed to submit response");
   178→		},
   179→	});
   180→
   181→	// Actions
   182→	const setAnswer = useCallback((questionId: string, value: AnswerValue) => {
   183→		setAnswers((prev) => {
   184→			const next = new Map(prev);
   185→			next.set(questionId, value);
   186→			return next;
   187→		});
   188→		setCurrentError(null);
   189→	}, []);
   190→
   191→	const goNext = useCallback(() => {
   192→		if (!currentQuestion) return;
   193→
   194→		// Validate current question
   195→		const answer = answers.get(currentQuestion.id);
   196→		const error = validateAnswer(currentQuestion, answer);
   197→		if (error) {
   198→			setCurrentError(error);
   199→			return;
   200→		}
   201→
   202→		if (canGoNext) {
   203→			const nextVisibleQuestion = visibleQuestions[currentVisibleIndex + 1];
   204→			if (nextVisibleQuestion) {
   205→				const nextIndex = sortedQuestions.findIndex(
   206→					(q) => q.id === nextVisibleQuestion.id,
   207→				);
   208→				setCurrentQuestionIndex(nextIndex);
   209→			}
   210→		}
   211→	}, [
   212→		currentQuestion,
   213→		answers,
   214→		canGoNext,
   215→		visibleQuestions,
   216→		currentVisibleIndex,
   217→		sortedQuestions,
   218→	]);
   219→
   220→	const goBack = useCallback(() => {
   221→		if (!canGoBack) return;
   222→
   223→		const prevVisibleQuestion = visibleQuestions[currentVisibleIndex - 1];
   224→		if (prevVisibleQuestion) {
   225→			const prevIndex = sortedQuestions.findIndex(
   226→				(q) => q.id === prevVisibleQuestion.id,
   227→			);
   228→			setCurrentQuestionIndex(prevIndex);
   229→		}
   230→	}, [canGoBack, visibleQuestions, currentVisibleIndex, sortedQuestions]);
   231→
   232→	const submit = useCallback(async () => {
   233→		if (!currentQuestion) return;
   234→
   235→		// Validate current question
   236→		const answer = answers.get(currentQuestion.id);
   237→		const error = validateAnswer(currentQuestion, answer);
   238→		if (error) {
   239→			setCurrentError(error);
   240→			return;
   241→		}
   242→
   243→		await submitMutation.mutateAsync();
   244→	}, [currentQuestion, answers, submitMutation]);
   245→
   246→	const clearError = useCallback(() => {
   247→		setCurrentError(null);
   248→	}, []);
   249→
   250→	const displayMode =
   251→		(survey.settings as SurveySettings | null)?.displayMode ?? "one_at_a_time";
   252→
   253→	const validateAllQuestions = useCallback(() => {
   254→		const errors = new Map<string, string>();
   255→		for (const question of visibleQuestions) {
   256→			const answer = answers.get(question.id);
   257→			const error = validateAnswer(question, answer);
   258→			if (error) {
   259→				errors.set(question.id, error);
   260→			}
   261→		}
   262→		return errors;
   263→	}, [visibleQuestions, answers]);
   264→
   265→	const value: SurveyRunnerContextValue = {
   266→		survey,
   267→		questions: sortedQuestions,
   268→		settings: survey.settings as SurveySettings | null,
   269→		logicRules,
   270→		displayMode,
   271→		answers,
   272→		currentQuestionIndex,
   273→		visibleQuestionIds,
   274→		visibleQuestions,
   275→		canGoBack,
   276→		canGoNext,
   277→		isComplete,
   278→		isSubmitting: submitMutation.isPending,
   279→		setAnswer,
   280→		goNext,
   281→		goBack,
   282→		submit,
   283→		validateAllQuestions,
   284→		fingerprint,
   285→		currentError,
   286→		clearError,
   287→	};
   288→
   289→	return (
   290→		<SurveyRunnerContext.Provider value={value}>
   291→			{children}
   292→		</SurveyRunnerContext.Provider>
   293→	);
   294→}
