    36→
    37→// Builder context for sharing state across components
    38→interface SurveyBuilderContextValue {
    39→	survey: Survey;
    40→	questions: Question[];
    41→	selectedQuestionId: string | null;
    42→	setSelectedQuestionId: (id: string | null) => void;
    43→	activeTab: "build" | "preview" | "share";
    44→	setActiveTab: (tab: "build" | "preview" | "share") => void;
    45→	onQuestionsChange: (questions: Question[]) => void;
