    58→export function useSurveyBuilder() {
    59→	const context = useContext(SurveyBuilderContext);
    60→	if (!context) {
    61→		throw new Error(
    62→			"useSurveyBuilder must be used within a SurveyBuilder component",
    63→		);
    64→	}
