    66→}
    67→
    68→// Drag item types
    69→interface PaletteDragItem {
    70→	type: "palette";
    71→	questionType: Question["type"];
    72→}
    73→
    74→interface QuestionDragItem {
    75→	type: "question";
    76→	id: string;
    77→}
    78→
    79→type DragItem = PaletteDragItem | QuestionDragItem;
    80→
    81→interface SurveyBuilderProps {
    82→	survey: Survey;
    83→	questions: Question[];
    84→	className?: string;
    85→}
    86→
    87→export function SurveyBuilder({
    88→	survey,
    89→	questions: initialQuestions,
    90→	className,
    91→}: SurveyBuilderProps) {
    92→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
    93→		null,
    94→	);
    95→	const [activeTab, setActiveTab] = useState<"build" | "preview" | "share">(
    96→		"build",
    97→	);
    98→	const [questions, setQuestions] = useState(initialQuestions);
    99→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   100→	const [overId, setOverId] = useState<string | null>(null);
   101→	const [paletteOpen, setPaletteOpen] = useState(false);
   102→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   103→	const [settingsOpen, setSettingsOpen] = useState(false);
   104→
   105→	// Responsive breakpoints
   106→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   107→
   108→	const queryClient = useQueryClient();
   109→
   110→	// Sync state when initialQuestions changes
   111→	useEffect(() => {
   112→		setQuestions(initialQuestions);
   113→	}, [initialQuestions]);
   114→
   115→	// Reorder mutation
   116→	const reorderMutation = useMutation(
   117→		orpc.question.reorder.mutationOptions({
   118→			onSuccess: () => {
   119→				queryClient.invalidateQueries({ queryKey: ["question"] });
   120→			},
   121→			onError: (error) => {
   122→				toast.error(error.message || "Failed to reorder questions");
   123→			},
   124→		}),
   125→	);
   126→
   127→	// DnD sensors
   128→	const sensors = useSensors(
   129→		useSensor(PointerSensor, {
   130→			activationConstraint: {
   131→				distance: 5,
   132→			},
   133→		}),
   134→		useSensor(KeyboardSensor, {
   135→			coordinateGetter: sortableKeyboardCoordinates,
   136→		}),
   137→	);
   138→
   139→	// Custom collision detection: pointerWithin for palette drops, closestCenter for canvas reordering
   140→	const collisionDetection: CollisionDetection = (args) => {
   141→		// If dragging from palette (has questionType), use pointerWithin for cross-container drops
   142→		if (args.active.data.current?.questionType) {
   143→			const pointerCollisions = pointerWithin(args);
   144→			if (pointerCollisions.length > 0) {
   145→				return pointerCollisions;
   146→			}
   147→		}
   148→		// For canvas reordering, use closestCenter for better sortable behavior
   149→		return closestCenter(args);
   150→	};
   151→
   152→	const handleDragStart = (event: DragStartEvent) => {
   153→		const { active } = event;
   154→		const data = active.data.current;
   155→
   156→		if (data?.questionType) {
   157→			// Dragging from palette
   158→			setActiveDragItem({
   159→				type: "palette",
   160→				questionType: data.questionType as Question["type"],
   161→			});
   162→		} else {
   163→			// Dragging existing question
   164→			setActiveDragItem({
   165→				type: "question",
   166→				id: active.id as string,
   167→			});
   168→		}
   169→	};
   170→
   171→	const handleDragOver = (event: DragOverEvent) => {
   172→		const { over } = event;
   173→		setOverId(over?.id as string | null);
   174→	};
   175→
   176→	const handleDragEnd = (event: DragEndEvent) => {
   177→		const { active, over } = event;
   178→		setOverId(null);
   179→
   180→		if (!over) {
   181→			setActiveDragItem(null);
   182→			return;
   183→		}
   184→
   185→		// Handle cancel drop
   186→		if (over.id === "palette-cancel-zone") {
   187→			setActiveDragItem(null);
   188→			return;
   189→		}
   190→
   191→		// Handle palette drop (from question type palette) - use tracked drop index
   192→		if (active.data.current?.questionType) {
   193→			const questionType = active.data.current.questionType as Question["type"];
   194→
   195→			// Calculate insert index based on over.id
   196→			const overIndex = questions.findIndex((q) => q.id === over.id);
   197→			const insertIndex = overIndex === -1 ? questions.length : overIndex;
   198→
   199→			// Optimistic update
   200→			const tempId = `temp-${crypto.randomUUID()}`;
   201→			const mockQuestion = createMockQuestion(questionType);
   202→			const optimisticQuestion = { ...mockQuestion, id: tempId };
   203→
   204→			const optimisticQuestions = [
   205→				...questions.slice(0, insertIndex).map((q, i) => ({ ...q, order: i })),
   206→				{ ...optimisticQuestion, order: insertIndex },
   207→				...questions
   208→					.slice(insertIndex)
   209→					.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   210→			];
   211→
   212→			setQuestions(optimisticQuestions);
   213→			setSelectedQuestionId(tempId);
   214→
   215→			// Create question and reorder
   216→			client.question
   217→				.create({
   218→					surveyId: survey.id,
   219→					type: questionType,
   220→					title: `New ${questionTypeLabels[questionType] || questionType}`,
   221→					order: insertIndex,
   222→				})
   223→				.then((newQuestion) => {
   224→					// Replace optimistic question with real one
   225→					setQuestions((currentQuestions) => {
   226→						const updatedQuestions = currentQuestions.map((q) =>
   227→							q.id === tempId ? newQuestion : q,
   228→						);
   229→						return updatedQuestions;
   230→					});
   231→
   232→					setSelectedQuestionId((currentId) =>
   233→						currentId === tempId ? newQuestion.id : currentId,
   234→					);
   235→
   236→					queryClient.invalidateQueries({ queryKey: ["question"] });
   237→
   238→					// Reorder all questions on backend to ensure consistency
   239→					const finalQuestions = [
   240→						...questions
   241→							.slice(0, insertIndex)
   242→							.map((q, i) => ({ ...q, order: i })),
   243→						{ ...newQuestion, order: insertIndex },
   244→						...questions
   245→							.slice(insertIndex)
   246→							.map((q, i) => ({ ...q, order: insertIndex + 1 + i })),
   247→					];
   248→
   249→					reorderMutation.mutate({
   250→						questions: finalQuestions.map((q) => ({
   251→							id: q.id,
   252→							order: q.order,
   253→						})),
   254→					});
   255→
   256→					toast.success("Question added");
   257→				})
   258→				.catch((error: Error) => {
   259→					// Revert on error
   260→					setQuestions(questions);
   261→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   262→					toast.error(error.message || "Failed to create question");
   263→				});
   264→
   265→			setActiveDragItem(null);
   266→			return;
   267→		}
   268→
   269→		// Handle reordering
   270→		if (active.id !== over.id && over.id !== "canvas") {
   271→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   272→			const newIndex = questions.findIndex((q) => q.id === over.id);
   273→
   274→			if (oldIndex !== -1 && newIndex !== -1) {
   275→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   276→					(q, index) => {
   277→						// Only create new object if order actually changed
   278→						if (q.order === index) {
   279→							return q; // Preserve reference
   280→						}
   281→						return { ...q, order: index };
   282→					},
   283→				);
   284→
   285→				setQuestions(newQuestions);
   286→
   287→				reorderMutation.mutate({
   288→					questions: newQuestions.map((q) => ({
   289→						id: q.id,
   290→						order: q.order,
   291→					})),
   292→				});
   293→			}
   294→		}
   295→
   296→		setActiveDragItem(null); // Always called last
   297→	};
   298→
   299→	const contextValue: SurveyBuilderContextValue = {
   300→		survey,
   301→		questions,
   302→		selectedQuestionId,
   303→		setSelectedQuestionId,
   304→		activeTab,
   305→		setActiveTab,
   306→		onQuestionsChange: setQuestions,
   307→		paletteOpen,
   308→		setPaletteOpen,
   309→		propertiesOpen,
   310→		setPropertiesOpen,
   311→		settingsOpen,
   312→		setSettingsOpen,
   313→	};
   314→
   315→	const safeQuestions = questions || [];
   316→
   317→	// Render drag overlay
   318→	const renderDragOverlay = () => {
   319→		if (!activeDragItem) return null;
   320→
   321→		if (activeDragItem.type === "palette") {
   322→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   323→			return (
   324→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   325→					<QuestionCardContent
   326→						question={mockQuestion}
   327→						isSelected={false}
   328→						hasLogic={false}
   329→						isOverlay={true}
   330→					/>
   331→				</div>
   332→			);
   333→		}
   334→
   335→		// Dragging existing question
   336→		const activeQuestion = safeQuestions.find(
   337→			(q) => q.id === activeDragItem.id,
   338→		);
   339→		if (activeQuestion) {
   340→			return (
   341→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   342→					<QuestionCardContent
   343→						question={activeQuestion}
   344→						isSelected={selectedQuestionId === activeQuestion.id}
   345→						hasLogic={false}
   346→						isOverlay={true}
   347→					/>
   348→				</div>
   349→			);
   350→		}
   351→
   352→		return null;
   353→	};
   354→
   355→	return (
   356→		<SurveyBuilderContext.Provider value={contextValue}>
   357→			<DndContext
   358→				sensors={sensors}
   359→				collisionDetection={collisionDetection}
   360→				onDragStart={handleDragStart}
   361→				onDragOver={handleDragOver}
   362→				onDragEnd={handleDragEnd}
   363→			>
   364→				<div className={cn("flex h-full flex-col", className)}>
   365→					<BuilderHeader
   366→						leftActions={
   367→							!isDesktop &&
   368→							activeTab === "build" && (
   369→								<div className="flex items-center gap-1">
   370→									<Button
   371→										variant="ghost"
   372→										size="icon"
   373→										onClick={() => setPaletteOpen(!paletteOpen)}
   374→									>
   375→										<PanelLeftClose className="h-4 w-4" />
   376→									</Button>
   377→								</div>
   378→							)
   379→						}
   380→						rightActions={
   381→							!isDesktop &&
   382→							activeTab === "build" && (
   383→								<div className="flex items-center gap-1">
   384→									<Button
   385→										variant="ghost"
   386→										size="icon"
   387→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   388→									>
   389→										<PanelRightClose className="h-4 w-4" />
   390→									</Button>
   391→								</div>
   392→							)
   393→						}
   394→					/>
   395→					<div className="flex flex-1 overflow-hidden">
   396→						{/* Left Palette - Responsive */}
   397→						{activeTab === "build" && (
   398→							<>
   399→								{/* Desktop: Fixed sidebar */}
   400→								{isDesktop && <QuestionPalette />}
   401→
   402→								{/* Tablet/Mobile: Sheet overlay */}
   403→								{!isDesktop && (
   404→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   405→										<SheetContent side="left" className="w-72 p-0">
   406→											<QuestionPalette />
   407→										</SheetContent>
   408→									</Sheet>
   409→								)}
   410→							</>
   411→						)}
   412→
   413→						{/* Canvas */}
   414→						<BuilderCanvas
   415→							questions={questions}
   416→							onQuestionsChange={setQuestions}
   417→							activeDragItem={activeDragItem}
   418→							overId={overId}
   419→						/>
   420→
   421→						{/* Right Properties Panel - Responsive */}
   422→						{activeTab === "build" && (
   423→							<>
   424→								{/* Desktop: Fixed sidebar */}
   425→								{isDesktop && <PropertiesPanel />}
   426→
   427→								{/* Tablet/Mobile: Sheet overlay */}
   428→								{!isDesktop && (
   429→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   430→										<SheetContent side="right" className="w-80 p-0">
   431→											<PropertiesPanel />
   432→										</SheetContent>
   433→									</Sheet>
   434→								)}
   435→							</>
   436→						)}
   437→					</div>
   438→				</div>
   439→
   440→				<DragOverlay dropAnimation={defaultDropAnimation}>
   441→					{renderDragOverlay()}
   442→				</DragOverlay>
   443→			</DndContext>
   444→		</SurveyBuilderContext.Provider>
   445→	);
   446→}
   447→
   448→export { BuilderCanvas } from "./builder-canvas";
