     1→import type { LogicRule, Question } from "@orksys-survey/db";
     2→import { useMemo } from "react";
     3→
     4→import {
     5→	type AnswersMap,
     6→	evaluateLogic,
     7→	getNextVisibleQuestionId,
     8→	type LogicEvaluationResult,
     9→} from "../utils/logic-engine";
    10→
    11→/**
    12→ * Configuration options for the logic evaluator hook.
    13→ */
    14→export interface UseLogicEvaluatorOptions {
    15→	/**
    16→	 * All logic rules for the survey.
    17→	 */
    18→	rules: LogicRule[];
    19→
    20→	/**
    21→	 * Current answers provided by the respondent.
    22→	 */
    23→	answers: AnswersMap;
    24→
    25→	/**
    26→	 * All questions in the survey.
    27→	 */
    28→	questions: Question[];
    29→
    30→	/**
    31→	 * The current question being displayed (optional).
    32→	 * Used for context in navigation actions.
    33→	 */
    34→	currentQuestionId?: string;
    35→}
    36→
    37→/**
    38→ * Result returned by the useLogicEvaluator hook.
    39→ */
    40→export interface UseLogicEvaluatorResult extends LogicEvaluationResult {
    41→	/**
    42→	 * Array of visible question IDs in order.
    43→	 */
    44→	visibleQuestionIdOrder: string[];
    45→
    46→	/**
    47→	 * Gets the next visible question ID after a given question.
    48→	 */
    49→	getNextQuestionId: (questionId: string) => string | null;
    50→
    51→	/**
    52→	 * Gets the previous visible question ID before a given question.
    53→	 */
    54→	getPreviousQuestionId: (questionId: string) => string | null;
    55→
    56→	/**
    57→	 * Checks if a specific question is visible.
    58→	 */
    59→	isQuestionVisible: (questionId: string) => boolean;
    60→
    61→	/**
    62→	 * Gets the index of a question in the visible order.
    63→	 */
    64→	getVisibleIndex: (questionId: string) => number;
    65→
    66→	/**
    67→	 * Total number of visible questions.
    68→	 */
    69→	visibleCount: number;
    70→}
    71→
    72→/**
    73→ * Gets the previous visible question ID before the current one.
    74→ */
    75→function getPreviousVisibleQuestionId(
    76→	currentQuestionId: string,
    77→	allQuestionIds: string[],
    78→	visibleQuestionIds: Set<string>,
    79→): string | null {
    80→	const currentIndex = allQuestionIds.indexOf(currentQuestionId);
    81→	if (currentIndex <= 0) {
    82→		return null;
    83→	}
    84→
    85→	for (let i = currentIndex - 1; i >= 0; i--) {
    86→		const prevId = allQuestionIds[i];
    87→		if (prevId && visibleQuestionIds.has(prevId)) {
    88→			return prevId;
    89→		}
    90→	}
    91→
    92→	return null;
    93→}
    94→
    95→/**
    96→ * React hook for evaluating survey logic rules at runtime.
    97→ *
    98→ * This hook takes the current state (answers, rules, questions) and computes:
    99→ * - Which questions should be visible
   100→ * - Any navigation actions to apply
   101→ * - Whether the survey should end early
   102→ *
   103→ * It automatically recalculates when answers or rules change.
   104→ *
   105→ * @example
   106→ * ```tsx
   107→ * const {
   108→ *   visibleQuestionIds,
   109→ *   navigationAction,
   110→ *   shouldEndSurvey,
   111→ *   getNextQuestionId,
   112→ *   isQuestionVisible,
   113→ * } = useLogicEvaluator({
   114→ *   rules: survey.logicRules,
   115→ *   answers: responses,
   116→ *   questions: survey.questions,
   117→ *   currentQuestionId: currentQuestion?.id,
   118→ * });
   119→ *
   120→ * // Handle navigation action
   121→ * useEffect(() => {
   122→ *   if (navigationAction?.type === 'jump_to' && navigationAction.targetQuestionId) {
   123→ *     goToQuestion(navigationAction.targetQuestionId);
   124→ *   }
   125→ * }, [navigationAction]);
   126→ * ```
   127→ */
   128→export function useLogicEvaluator({
   129→	rules,
   130→	answers,
   131→	questions,
   132→	currentQuestionId,
   133→}: UseLogicEvaluatorOptions): UseLogicEvaluatorResult {
   134→	// Memoize question IDs array for stable references
   135→	const allQuestionIds = useMemo(
   136→		() =>
   137→			questions
   138→				.map((q) => q.id)
   139→				.sort((a, b) => {
   140→					const orderA = questions.find((q) => q.id === a)?.order ?? 0;
   141→					const orderB = questions.find((q) => q.id === b)?.order ?? 0;
   142→					return orderA - orderB;
   143→				}),
   144→		[questions],
   145→	);
   146→
   147→	// Evaluate logic rules
   148→	const evaluationResult = useMemo(() => {
   149→		return evaluateLogic(rules, answers, allQuestionIds, currentQuestionId);
   150→	}, [rules, answers, allQuestionIds, currentQuestionId]);
   151→
   152→	// Compute ordered array of visible question IDs
   153→	const visibleQuestionIdOrder = useMemo(() => {
   154→		return allQuestionIds.filter((id) =>
   155→			evaluationResult.visibleQuestionIds.has(id),
   156→		);
   157→	}, [allQuestionIds, evaluationResult.visibleQuestionIds]);
   158→
   159→	// Helper functions
   160→	const getNextQuestionId = (questionId: string): string | null => {
   161→		return getNextVisibleQuestionId(
   162→			questionId,
   163→			allQuestionIds,
   164→			evaluationResult.visibleQuestionIds,
   165→		);
   166→	};
   167→
   168→	const getPreviousQuestionId = (questionId: string): string | null => {
   169→		return getPreviousVisibleQuestionId(
   170→			questionId,
   171→			allQuestionIds,
   172→			evaluationResult.visibleQuestionIds,
   173→		);
   174→	};
   175→
   176→	const isQuestionVisible = (questionId: string): boolean => {
   177→		return evaluationResult.visibleQuestionIds.has(questionId);
   178→	};
   179→
   180→	const getVisibleIndex = (questionId: string): number => {
   181→		return visibleQuestionIdOrder.indexOf(questionId);
   182→	};
   183→
   184→	return {
   185→		...evaluationResult,
   186→		visibleQuestionIdOrder,
   187→		getNextQuestionId,
   188→		getPreviousQuestionId,
   189→		isQuestionVisible,
   190→		getVisibleIndex,
   191→		visibleCount: visibleQuestionIdOrder.length,
   192→	};
   193→}
