     3→import * as React from "react";
     4→
     5→/**
     6→ * Generates a stable browser fingerprint using available browser APIs.
     7→ * Combines multiple browser attributes to create a unique identifier.
     8→ *
     9→ * @returns A SHA-256 hash string representing the browser fingerprint, or null on server-side
    10→ */
    11→export function useFingerprint(): string | null {
    12→	const [fingerprint, setFingerprint] = React.useState<string | null>(null);
    13→
    14→	React.useEffect(() => {
    15→		// Return null for server-side rendering
    16→		if (typeof window === "undefined") {
    17→			return;
    18→		}
    19→
    20→		// Collect browser attributes for fingerprinting
    21→		const attributes = [
    22→			navigator.userAgent,
    23→			navigator.language,
    24→			`${screen.width}x${screen.height}`,
    25→			new Date().getTimezoneOffset().toString(),
    26→		].join("|");
    27→
    28→		// Generate SHA-256 hash
    29→		async function generateHash() {
    30→			try {
    31→				const encoder = new TextEncoder();
    32→				const data = encoder.encode(attributes);
    33→				const hashBuffer = await crypto.subtle.digest("SHA-256", data);
    34→
    35→				// Convert buffer to hex string
    36→				const hashArray = Array.from(new Uint8Array(hashBuffer));
    37→				const hashHex = hashArray
    38→					.map((b) => b.toString(16).padStart(2, "0"))
    39→					.join("");
    40→
    41→				setFingerprint(hashHex);
    42→			} catch {
    43→				// Fallback to simple hash if crypto.subtle fails
    44→				const simpleHash = simpleHashString(attributes);
    45→				setFingerprint(simpleHash);
    46→			}
    47→		}
    48→
    49→		generateHash();
    50→	}, []);
    51→
    52→	return fingerprint;
    53→}
    54→
    55→/**
    56→ * Simple fallback hash function for environments where crypto.subtle is unavailable.
    57→ * Uses a basic DJB2-style hash algorithm.
    58→ */
    59→function simpleHashString(str: string): string {
    60→	let hash = 5381;
    61→	for (let i = 0; i < str.length; i++) {
    62→		hash = (hash << 5) + hash + str.charCodeAt(i); // hash * 33 + c
    63→	}
    64→	return (hash >>> 0).toString(16); // Convert to unsigned and hex
    65→}
