   301→									onConfigChange({
   302→										...config,
   303→										minLength: e.target.value
   304→											? Number(e.target.value)
   305→											: undefined,
   306→									})
   307→								}
   308→								placeholder="0"
   309→							/>
   310→						</div>
   311→						<div className="space-y-2">
   312→							<Label className="text-xs uppercase tracking-wide">Max</Label>
   313→							<Input
