   216→interface QuestionCardProps {
   217→	question: Question;
   218→	isSelected: boolean;
   219→	onSelect: () => void;
   220→	questions: Question[];
   221→	onQuestionsChange: (questions: Question[]) => void;
   222→}
   223→
   224→const animateLayoutChanges: AnimateLayoutChanges = () => {
   225→	return false;
   226→};
   227→
   228→export const QuestionCard = memo(function QuestionCard({
   229→	question,
   230→	isSelected,
   231→	onSelect,
   232→	questions,
   233→	onQuestionsChange,
   234→}: QuestionCardProps) {
   235→	const queryClient = useQueryClient();
   236→
   237→	// Sortable for reordering within canvas
   238→	const {
   239→		attributes,
   240→		listeners,
   241→		setNodeRef: setSortableRef,
   242→		transform,
   243→		transition,
   244→		isDragging,
   245→	} = useSortable({
   246→		id: question.id,
   247→		animateLayoutChanges,
   248→	});
   249→
   250→	// Droppable for palette item drops
   251→	const { setNodeRef: setDroppableRef, isOver } = useDroppable({
   252→		id: question.id,
   253→	});
   254→
   255→	// Combine refs so element is both sortable and droppable
   256→	const setNodeRef = (node: HTMLElement | null) => {
   257→		setSortableRef(node);
   258→		setDroppableRef(node);
   259→	};
   260→
   261→	const deleteMutation = useMutation(
   262→		orpc.question.delete.mutationOptions({
   263→			onSuccess: () => {
   264→				onQuestionsChange(questions.filter((q) => q.id !== question.id));
   265→				queryClient.invalidateQueries({ queryKey: ["question"] });
   266→				toast.success("Question deleted");
   267→			},
   268→			onError: (error) => {
   269→				toast.error(error.message || "Failed to delete question");
   270→			},
   271→		}),
   272→	);
   273→
   274→	// Query logic rules to check if this question has any
   275→	const logicRules = useQuery(
   276→		orpc.logicRule.list.queryOptions({
   277→			input: { surveyId: question.surveyId },
   278→		}),
   279→	);
   280→
   281→	const hasLogic = logicRules.data?.some(
   282→		(rule) => rule.sourceQuestionId === question.id,
   283→	);
   284→
   285→	const style = {
   286→		transform: CSS.Translate.toString(transform), // Use Translate for smoother sorting
   287→		transition,
   288→		zIndex: isDragging ? 50 : undefined,
   289→	};
   290→
   291→	return (
   292→		<motion.div
   293→			ref={setNodeRef}
   294→			style={style}
   295→			className={cn(isDragging && "z-50")}
   296→		>
   297→			<QuestionCardContent
   298→				question={question}
   299→				isSelected={isSelected}
   300→				hasLogic={hasLogic}
   301→				onSelect={onSelect}
   302→				onDelete={() => deleteMutation.mutate({ id: question.id })}
   303→				isDeleting={deleteMutation.isPending}
   304→				dragHandleProps={{ ...attributes, ...listeners }}
   305→				isDragging={isDragging}
   306→				isOver={isOver}
   307→			/>
   308→		</motion.div>
   309→	);
   310→});
   311→

