    ...etc
  providers.tsx                # App-level providers
  theme-provider.tsx
  header.tsx
  ...etc
```

### 2. State Management Patterns

#### A. Context Pattern (Most Common)

Two primary examples of the **Context + Custom Hook + Provider** pattern:

**SurveyBuilder** (`/Users/orksys/Projects/orksys-survey/apps/web/src/components/survey-builder/index.tsx`):
```typescript
// Context definition
interface SurveyBuilderContextValue {
  survey: Survey;
  questions: Question[];
  selectedQuestionId: string | null;
  setSelectedQuestionId: (id: string | null) => void;
  activeTab: "build" | "preview" | "share";
  setActiveTab: (tab: "build" | "preview" | "share") => void;
  onQuestionsChange: (questions: Question[]) => void;
  paletteOpen: boolean;
  setPaletteOpen: (open: boolean) => void;
  propertiesOpen: boolean;
  setPropertiesOpen: (open: boolean) => void;
  settingsOpen: boolean;
  setSettingsOpen: (open: boolean) => void;
}

const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(null);

// Custom hook with error boundary
export function useSurveyBuilder() {
  const context = useContext(SurveyBuilderContext);
  if (!context) {
    throw new Error("useSurveyBuilder must be used within a SurveyBuilder component");
  }
  return context;
}
```

**SurveyRunner** (`/Users/orksys/Projects/orksys-survey/apps/web/src/components/survey-runner/context.tsx`):
```typescript
interface SurveyRunnerContextValue {
  // Survey data
  survey: Survey;
