   261→					if (selectedQuestionId === tempId) setSelectedQuestionId(null);
   262→					toast.error(error.message || "Failed to create question");
   263→				});
   264→
   265→			setActiveDragItem(null);
   266→			return;
   267→		}
   268→
   269→		// Handle reordering
   270→		if (active.id !== over.id && over.id !== "canvas") {
   271→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   272→			const newIndex = questions.findIndex((q) => q.id === over.id);
   273→
   274→			if (oldIndex !== -1 && newIndex !== -1) {
   275→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   276→					(q, index) => {
   277→						// Only create new object if order actually changed
   278→						if (q.order === index) {
   279→							return q; // Preserve reference
   280→						}
   281→						return { ...q, order: index };
   282→					},
   283→				);
   284→
   285→				setQuestions(newQuestions);
   286→
   287→				reorderMutation.mutate({
   288→					questions: newQuestions.map((q) => ({
   289→						id: q.id,
   290→						order: q.order,
   291→					})),
   292→				});
   293→			}
   294→		}
   295→
   296→		setActiveDragItem(null); // Always called last
   297→	};
   298→
   299→	const contextValue: SurveyBuilderContextValue = {
   300→		survey,
   301→		questions,
   302→		selectedQuestionId,
   303→		setSelectedQuestionId,
   304→		activeTab,
   305→		setActiveTab,
   306→		onQuestionsChange: setQuestions,
   307→		paletteOpen,
   308→		setPaletteOpen,
   309→		propertiesOpen,
   310→		setPropertiesOpen,
   311→		settingsOpen,
   312→		setSettingsOpen,
   313→	};
   314→
   315→	const safeQuestions = questions || [];
   316→
   317→	// Render drag overlay
   318→	const renderDragOverlay = () => {
   319→		if (!activeDragItem) return null;
   320→
   321→		if (activeDragItem.type === "palette") {
   322→			const mockQuestion = createMockQuestion(activeDragItem.questionType);
   323→			return (
   324→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   325→					<QuestionCardContent
   326→						question={mockQuestion}
   327→						isSelected={false}
   328→						hasLogic={false}
   329→						isOverlay={true}
   330→					/>
   331→				</div>
   332→			);
   333→		}
   334→
   335→		// Dragging existing question
   336→		const activeQuestion = safeQuestions.find(
   337→			(q) => q.id === activeDragItem.id,
   338→		);
   339→		if (activeQuestion) {
   340→			return (
   341→				<div className="w-[calc(100vw-3rem)] max-w-2xl">
   342→					<QuestionCardContent
   343→						question={activeQuestion}
   344→						isSelected={selectedQuestionId === activeQuestion.id}
   345→						hasLogic={false}
   346→						isOverlay={true}
   347→					/>
   348→				</div>
   349→			);
   350→		}
   351→
   352→		return null;
   353→	};
   354→
   355→	return (
   356→		<SurveyBuilderContext.Provider value={contextValue}>
   357→			<DndContext
   358→				sensors={sensors}
   359→				collisionDetection={collisionDetection}
   360→				onDragStart={handleDragStart}
   361→				onDragOver={handleDragOver}
   362→				onDragEnd={handleDragEnd}
   363→			>
   364→				<div className={cn("flex h-full flex-col", className)}>
   365→					<BuilderHeader
   366→						leftActions={
   367→							!isDesktop &&
   368→							activeTab === "build" && (
   369→								<div className="flex items-center gap-1">
   370→									<Button
   371→										variant="ghost"
   372→										size="icon"
   373→										onClick={() => setPaletteOpen(!paletteOpen)}
   374→									>
   375→										<PanelLeftClose className="h-4 w-4" />
   376→									</Button>
   377→								</div>
   378→							)
   379→						}
   380→						rightActions={
   381→							!isDesktop &&
   382→							activeTab === "build" && (
   383→								<div className="flex items-center gap-1">
   384→									<Button
   385→										variant="ghost"
   386→										size="icon"
   387→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   388→									>
   389→										<PanelRightClose className="h-4 w-4" />
   390→									</Button>
   391→								</div>
   392→							)
   393→						}
   394→					/>
   395→					<div className="flex flex-1 overflow-hidden">
   396→						{/* Left Palette - Responsive */}
   397→						{activeTab === "build" && (
   398→							<>
   399→								{/* Desktop: Fixed sidebar */}
   400→								{isDesktop && <QuestionPalette />}
   401→
   402→								{/* Tablet/Mobile: Sheet overlay */}
   403→								{!isDesktop && (
   404→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   405→										<SheetContent side="left" className="w-72 p-0">
   406→											<QuestionPalette />
   407→										</SheetContent>
   408→									</Sheet>
   409→								)}
   410→							</>
   411→						)}
   412→
   413→						{/* Canvas */}
   414→						<BuilderCanvas
   415→							questions={questions}
   416→							onQuestionsChange={setQuestions}
   417→							activeDragItem={activeDragItem}
   418→							overId={overId}
   419→						/>
   420→
   421→						{/* Right Properties Panel - Responsive */}
   422→						{activeTab === "build" && (
   423→							<>
   424→								{/* Desktop: Fixed sidebar */}
   425→								{isDesktop && <PropertiesPanel />}
   426→
   427→								{/* Tablet/Mobile: Sheet overlay */}
   428→								{!isDesktop && (
   429→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   430→										<SheetContent side="right" className="w-80 p-0">
   431→											<PropertiesPanel />
   432→										</SheetContent>
   433→									</Sheet>
   434→								)}
   435→							</>
   436→						)}
   437→					</div>
   438→				</div>
   439→
   440→				<DragOverlay dropAnimation={defaultDropAnimation}>
   441→					{renderDragOverlay()}
   442→				</DragOverlay>
   443→			</DndContext>
   444→		</SurveyBuilderContext.Provider>
   445→	);
   446→}
