   257→		case "checkbox":
   258→		case "dropdown":
   259→			return (
   260→				<ChoiceEditor
   261→					config={config}
   262→					onChange={onConfigChange}
   263→					allowMultiple={question.type === "checkbox"}
   264→				/>
   265→			);
   266→
   267→		case "rating":
   268→		case "nps":
   269→		case "linear_scale":
   270→			return (
   271→				<RatingEditor
   272→					config={config}
   273→					onChange={onConfigChange}
   274→					type={question.type}
   275→				/>
   276→			);
   277→
   278→		case "text":
   279→		case "textarea":
   280→			return (
   281→				<div className="space-y-4">
   282→					<div className="space-y-2">
   283→						<Label className="text-xs uppercase tracking-wide">
   284→							Placeholder
   285→						</Label>
   286→						<Input
   287→							value={config.placeholder || ""}
   288→							onChange={(e) =>
   289→								onConfigChange({ ...config, placeholder: e.target.value })
   290→							}
   291→							placeholder="Enter placeholder text"
   292→						/>
   293→					</div>
   294→					<div className="grid grid-cols-2 gap-3">
   295→						<div className="space-y-2">
   296→							<Label className="text-xs uppercase tracking-wide">Min</Label>
   297→							<Input
   298→								type="number"
   299→								value={config.minLength || ""}
   300→								onChange={(e) =>
   301→									onConfigChange({
   302→										...config,
   303→										minLength: e.target.value
   304→											? Number(e.target.value)
   305→											: undefined,
   306→									})
   307→								}
   308→								placeholder="0"
   309→							/>
   310→						</div>
   311→						<div className="space-y-2">
   312→							<Label className="text-xs uppercase tracking-wide">Max</Label>
   313→							<Input
   314→								type="number"
   315→								value={config.maxLength || ""}
   316→								onChange={(e) =>
