   105→	const sourceQuestion = questions.find((q) => q.id === sourceQuestionId);
   106→
   107→	// Determine if we need a condition value input
   108→	const needsConditionValue = (operator: string) => {
   109→		return !["is_empty", "is_not_empty"].includes(operator);
   110→	};
   111→
   112→	// Determine if we need a target question select
   113→	const needsTargetQuestion = (action: string) => {
   114→		return ["jump_to", "show", "hide"].includes(action);
   115→	};
   116→
   117→	const form = useForm({
   118→		defaultValues: {
   119→			operator: (existingRule?.operator as string) || "equals",
   120→			conditionValue:
   121→				existingRule?.conditionValue !== null &&
   122→				existingRule?.conditionValue !== undefined
   123→					? String(existingRule.conditionValue)
   124→					: "",
   125→			action: (existingRule?.action as string) || "jump_to",
   126→			targetQuestionId: existingRule?.targetQuestionId || "",
   127→		},
   128→		onSubmit: async ({ value }) => {
   129→			const data = {
   130→				operator: value.operator as
   131→					| "equals"
   132→					| "not_equals"
   133→					| "contains"
   134→					| "greater_than"
   135→					| "less_than"
   136→					| "is_empty"
   137→					| "is_not_empty",
   138→				action: value.action as
   139→					| "jump_to"
   140→					| "skip"
   141→					| "show"
   142→					| "hide"
   143→					| "end_survey",
   144→				conditionValue: needsConditionValue(value.operator)
   145→					? value.conditionValue
   146→					: undefined,
   147→				targetQuestionId: needsTargetQuestion(value.action)
   148→					? value.targetQuestionId
   149→					: undefined,
   150→			};
   151→
   152→			if (existingRule) {
   153→				await updateMutation.mutateAsync({
   154→					id: existingRule.id,
   155→					data,
   156→				});
   157→			} else {
   158→				await createMutation.mutateAsync({
   159→					surveyId,
   160→					sourceQuestionId,
   161→					...data,
   162→				});
   163→			}
   164→		},
   165→		validators: {
   166→			onSubmit: logicRuleSchema,
   167→		},
   168→	});
   169→
   170→	const isSubmitting = createMutation.isPending || updateMutation.isPending;
   171→
   172→	// Get options for the source question (for choice-based questions)
   173→	const getSourceOptions = () => {
   174→		const config = sourceQuestion?.config;
   175→		if (config?.options) {
   176→			return config.options;
   177→		}
   178→		return null;
   179→	};
   180→
   181→	const sourceOptions = getSourceOptions();
   182→
   183→	return (
   184→		<form
   185→			onSubmit={(e) => {
   186→				e.preventDefault();
   187→				e.stopPropagation();
   188→				form.handleSubmit();
   189→			}}
   190→			className="space-y-4"
   191→		>
   192→			{/* Source Question Info */}
   193→			<div className="rounded-lg bg-neutral-50 p-3">
   194→				<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   195→					Source Question
   196→				</Label>
   197→				<p className="mt-1 font-medium text-sm">{sourceQuestion?.title}</p>
   198→			</div>
   199→
   200→			{/* Operator Select */}
   201→			<form.Field name="operator">
   202→				{(field) => (
   203→					<div className="space-y-2">
   204→						<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   205→							Condition
   206→						</Label>
   207→						<Select
   208→							value={field.state.value}
   209→							onValueChange={(value) => field.handleChange(value)}
   210→						>
   211→							<SelectTrigger>
   212→								<SelectValue placeholder="Select condition" />
   213→							</SelectTrigger>
   214→							<SelectContent>
   215→								{operatorLabels.map(([value, label]) => (
   216→									<SelectItem key={value} value={value}>
   217→										{label}
   218→									</SelectItem>
   219→								))}
   220→							</SelectContent>
   221→						</Select>
   222→					</div>
   223→				)}
   224→			</form.Field>
   225→
   226→			{/* Condition Value */}
   227→			<form.Field name="operator">
   228→				{(operatorField) =>
   229→					needsConditionValue(operatorField.state.value) && (
   230→						<form.Field name="conditionValue">
   231→							{(field) => (
   232→								<div className="space-y-2">
   233→									<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   234→										Value
   235→									</Label>
   236→									{sourceOptions ? (
   237→										<Select
   238→											value={field.state.value}
   239→											onValueChange={(value) => field.handleChange(value)}
   240→										>
   241→											<SelectTrigger>
   242→												<SelectValue placeholder="Select value" />
   243→											</SelectTrigger>
   244→											<SelectContent>
   245→												{sourceOptions.map((option) => (
   246→													<SelectItem key={option.value} value={option.value}>
   247→														{option.label}
   248→													</SelectItem>
   249→												))}
   250→											</SelectContent>
   251→										</Select>
   252→									) : (
   253→										<Input
   254→											value={field.state.value}
   255→											onChange={(e) => field.handleChange(e.target.value)}
   256→											placeholder="Enter value"
   257→										/>
   258→									)}
   259→								</div>
   260→							)}
   261→						</form.Field>
   262→					)
   263→				}
   264→			</form.Field>
   265→
   266→			{/* Action Select */}
   267→			<form.Field name="action">
   268→				{(field) => (
   269→					<div className="space-y-2">
   270→						<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   271→							Action
   272→						</Label>
   273→						<Select
   274→							value={field.state.value}
   275→							onValueChange={(value) => field.handleChange(value)}
   276→						>
   277→							<SelectTrigger>
   278→								<SelectValue placeholder="Select action" />
   279→							</SelectTrigger>
   280→							<SelectContent>
   281→								{actionLabels.map(([value, label]) => (
   282→									<SelectItem key={value} value={value}>
   283→										{label}
   284→									</SelectItem>
   285→								))}
   286→							</SelectContent>
   287→						</Select>
   288→					</div>
   289→				)}
   290→			</form.Field>
   291→
   292→			{/* Target Question Select */}
   293→			<form.Field name="action">
   294→				{(actionField) =>
   295→					needsTargetQuestion(actionField.state.value) && (
   296→						<form.Field name="targetQuestionId">
   297→							{(field) => (
   298→								<div className="space-y-2">
   299→									<Label className="text-neutral-500 text-xs uppercase tracking-wide">
   300→										Target Question
   301→									</Label>
   302→									<Select
   303→										value={field.state.value}
   304→										onValueChange={(value) => field.handleChange(value)}
   305→									>
   306→										<SelectTrigger>
   307→											<SelectValue placeholder="Select question" />
   308→										</SelectTrigger>
   309→										<SelectContent>
   310→											{targetQuestions.map((question) => (
   311→												<SelectItem key={question.id} value={question.id}>
   312→													{question.title}
   313→												</SelectItem>
   314→											))}
   315→										</SelectContent>
   316→									</Select>
   317→									{targetQuestions.length === 0 && (
   318→										<p className="text-amber-600 text-xs">
   319→											No questions available after this one. Add more questions
   320→											or use a different action.
   321→										</p>
   322→									)}
   323→								</div>
   324→							)}
   325→						</form.Field>
   326→					)
   327→				}
   328→			</form.Field>
   329→
   330→			{/* Validation Errors */}
   331→			{validateMutation.data && !validateMutation.data.valid && (
   332→				<div className="rounded-lg border border-amber-200 bg-amber-50 p-3">
   333→					<p className="font-medium text-amber-800 text-sm">
   334→						Validation Warning
   335→					</p>
   336→					{validateMutation.data.hasCircularDependency && (
   337→						<p className="mt-1 text-amber-700 text-xs">
   338→							Circular dependency detected in logic rules.
   339→						</p>
   340→					)}
   341→					{validateMutation.data.selfReferentialRules.length > 0 && (
   342→						<p className="mt-1 text-amber-700 text-xs">
   343→							Some rules reference themselves.
   344→						</p>
   345→					)}
   346→				</div>
   347→			)}
   348→
   349→			{/* Actions */}
   350→			<div className="flex gap-3 pt-4">
   351→				<Button
   352→					type="button"
   353→					variant="outline"
   354→					onClick={onCancel}
   355→					className="flex-1"
   356→				>
   357→					Cancel
   358→				</Button>
   359→				<form.Subscribe>
   360→					{(state) => (
   361→						<Button
   362→							type="submit"
   363→							disabled={!state.canSubmit || isSubmitting}
   364→							className="flex-1"
   365→						>
   366→							{isSubmitting ? (
   367→								<Loader2 className="h-4 w-4 animate-spin" />
   368→							) : existingRule ? (
   369→								"Update Rule"
   370→							) : (
   371→								"Create Rule"
   372→							)}
   373→						</Button>
   374→					)}
   375→				</form.Subscribe>
   376→			</div>
   377→		</form>
   378→	);
   379→}
