   237→
   238→// Helper to calculate NPS score
   239→function calculateNPSScore(
   240→	distribution: Array<{ value: string; count: number }>,
   241→): number {
   242→	let promoters = 0;
   243→	let passives = 0;
   244→	let detractors = 0;
   245→	let total = 0;
   246→
   247→	for (const item of distribution) {
   248→		const score = Number.parseInt(item.value, 10);
   249→		if (Number.isNaN(score)) continue;
   250→
   251→		total += item.count;
   252→		if (score >= 9) promoters += item.count;
   253→		else if (score >= 7) passives += item.count;
   254→		else detractors += item.count;
   255→	}
   256→
   257→	if (total === 0) return 0;
   258→
   259→	const promoterPercent = (promoters / total) * 100;
   260→	const detractorPercent = (detractors / total) * 100;
   261→
   262→	return Math.round(promoterPercent - detractorPercent);
   263→}
