    30→
    31→function getErrorMessage(error: unknown): string | null {
    32→	if (!error) return null;
    33→
    34→	if (typeof error === "string") {
    35→		return error;
    36→	}
    37→
    38→	if (Array.isArray(error)) {
    39→		for (const issue of error) {
    40→			const message = getErrorMessage(issue);
    41→			if (message) {
    42→				return message;
    43→			}
    44→		}
    45→		return null;
    46→	}
    47→
    48→	if (typeof error === "object" && error !== null) {
    49→		const maybeError = error as { message?: unknown };
    50→		if (typeof maybeError.message === "string") {
    51→			return maybeError.message;
    52→		}
    53→	}
    54→
    55→	return null;
    56→}
    57→
    58→function SignIn() {
    59→	const passwordInputRef = useRef<TextInput>(null);
    60→	const { toast } = useToast();
    61→
    62→	const form = useForm({
    63→		defaultValues: {
    64→			email: "",
    65→			password: "",
    66→		},
    67→		validators: {
    68→			onSubmit: signInSchema,
    69→		},
    70→		onSubmit: async ({ value, formApi }) => {
    71→			await authClient.signIn.email(
    72→				{
    73→					email: value.email.trim(),
    74→					password: value.password,
    75→				},
    76→				{
    77→					onError(error) {
    78→						toast.show({
    79→							variant: "danger",
    80→							label: error.error?.message || "Failed to sign in",
    81→						});
    82→					},
    83→					onSuccess() {
    84→						formApi.reset();
    85→						toast.show({
    86→							variant: "success",
    87→							label: "Signed in successfully",
    88→						});
    89→						queryClient.refetchQueries();
    90→					},
    91→				},
    92→			);
    93→		},
    94→	});
    95→
    96→	return (
    97→		<Surface variant="secondary" className="rounded-lg p-4">
    98→			<Text className="mb-4 font-medium text-foreground">Sign In</Text>
    99→
   100→			<form.Subscribe
   101→				selector={(state) => ({
   102→					isSubmitting: state.isSubmitting,
   103→					validationError: getErrorMessage(state.errorMap.onSubmit),
   104→				})}
   105→			>
   106→				{({ isSubmitting, validationError }) => {
   107→					const formError = validationError;
   108→
   109→					return (
   110→						<>
   111→							<FieldError isInvalid={!!formError} className="mb-3">
   112→								{formError}
   113→							</FieldError>
   114→
   115→							<View className="gap-3">
   116→								<form.Field name="email">
   117→									{(field) => (
   118→										<TextField>
   119→											<Label>Email</Label>
   120→											<Input
   121→												value={field.state.value}
   122→												onBlur={field.handleBlur}
   123→												onChangeText={field.handleChange}
   124→												placeholder="email@example.com"
   125→												keyboardType="email-address"
   126→												autoCapitalize="none"
   127→												autoComplete="email"
   128→												textContentType="emailAddress"
   129→												returnKeyType="next"
   130→												blurOnSubmit={false}
   131→												onSubmitEditing={() => {
   132→													passwordInputRef.current?.focus();
