    36→function getErrorMessage(error: unknown): string | null {
    37→	if (!error) return null;
    38→
    39→	if (typeof error === "string") {
    40→		return error;
    41→	}
    42→
    43→	if (Array.isArray(error)) {
    44→		for (const issue of error) {
    45→			const message = getErrorMessage(issue);
    46→			if (message) {
    47→				return message;
    48→			}
    49→		}
    50→		return null;
    51→	}
    52→
    53→	if (typeof error === "object" && error !== null) {
    54→		const maybeError = error as { message?: unknown };
    55→		if (typeof maybeError.message === "string") {
    56→			return maybeError.message;
    57→		}
    58→	}
    59→
    60→	return null;
    61→}
