function FileUploadQuestion({
	question,
	value: _value,
	onChange: _onChange,
	error,
}: {
	question: Question;
	value: unknown;
	onChange: (value: unknown) => void;
	error?: string | null;
}) {
	const maxFiles = question.config?.maxFiles ?? 1;

	return (
		<div className="space-y-2">
			<label className="block font-medium text-neutral-900">
				{question.title}
				{question.required && <span className="ml-1 text-red-500">*</span>}
			</label>
			{question.description && (
				<p className="text-neutral-600 text-sm">{question.description}</p>
			)}
			<div className="mt-3 flex justify-center rounded-lg border border-neutral-300 border-dashed px-6 py-10">
				<div className="text-center">
					<p className="text-neutral-600 text-sm">
						Drag and drop files here, or click to select
					</p>
					<p className="mt-1 text-neutral-500 text-xs">
						Up to {maxFiles} file{maxFiles > 1 ? "s" : ""}
					</p>
				</div>
			</div>
			{error && <p className="text-red-500 text-sm">{error}</p>}
		</div>
	);
}

export function QuestionRenderer({ question }: QuestionRendererProps) {
	const { answers, setAnswer, currentError } = useSurveyRunner();
	const value = answers.get(question.id);
	const error = currentError;

	const handleChange = (newValue: unknown) => {
		setAnswer(question.id, newValue);
	};

	switch (question.type) {
		case "text":
			return (
				<TextQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "textarea":
			return (
				<TextareaQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "multiple_choice":
			return (
				<ChoiceQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "checkbox":
			return (
				<CheckboxQuestion
					question={question}
					value={value as string[] | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "dropdown":
			return (
				<DropdownQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "rating":
			return (
				<RatingQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "nps":
			return (
				<NpsQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "linear_scale":
			return (
				<LinearScaleQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "date":
			return (
				<DateQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "email":
			return (
				<EmailQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "phone":
			return (
				<PhoneQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "file_upload":
			return (
				<FileUploadQuestion
					question={question}
					value={value}
					onChange={handleChange}
					error={error}
				/>
			);
		default:
			return (
				<div className="text-neutral-500">
					Unknown question type: {question.type}
				</div>
			);
	}
}

